const CACHE='aventure-velo-v80-fatigue2';
const FILES=['./','./index.html','./style.css','./app.js','./card-editor.js','./event-cards.js','./event-card-engine.js','./event-card-ui.js','./engine.js','./simulator.js','./europe.js','./europe-map.js','./map-library.js','./cards.js','./rules.js','./voyages.js','./tile-art.js','./assets/europe/board-data.js','./assets/europe/nouvelle-carte.png','./assets/voyages/cards.png','./assets/voyages/atlantique-alpes.png','./assets/voyages/routes-est.png','./assets/voyages/balkans.png','./manifest.json','./icon.svg','./icon-192.png','./icon-512.png'];
FILES.push('./style.css?v=fatigue2','./app.js?v=fatigue2','./tutorial.js','./immersion.js','./menus.js','./board-camera.js','./board-roads.js','./routes.js','./assets/europe/routes-data.js','./weather.js','./carnet-data.js','./encounters.js','./online.js','./rules-help.js','./saves.js','./display-prefs.js','./assets/europe/decor-data.js','./board-renderer.js','./board-renderer-svg.js','./board-hit-test.js','./terrain-art.js','./terrain-dynamic.js','./terrain-variants.js','./terrain-patches.js','./assets/terrain/europe-terrain.webp','./assets/terrain/europe-ground.webp','./assets/terrain/patches.webp');
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});
self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===self.location.origin)e.respondWith(fetch(e.request,{cache:'no-cache'}).catch(()=>caches.match(e.request)));});
// fetch : toujours vérifier la dernière version (sinon un fichier du jeu peut rester ancien 10 min).
